        if is_peak_arr[i]:
            bit_update(i + 1, 1)

    answer = []

    for query in queries:
        if query[0] == 1:
            _, l, r = query
            # Peaks can only be at positions 1..n-2 (0-indexed), which are 2..n-1 in 1-indexed
            # In a subarray nums[l..r], peaks can only be at positions l+1..r-1 (0-indexed)
            # Which are (l+1)+1..(r-1)+1 = l+2..r in 1-indexed
            count = bit_range_query(l + 2, r)
            answer.append(count)
        else:
            _, index, val = query
            old_val = nums[index]
            if old_val == val:
                continue

            affected = set()
            if 1 <= index <= n - 2:
                affected.add(index)
            if 1 <= index - 1 <= n - 2:
                affected.add(index - 1)
            if 1 <= index + 1 <= n - 2:
                affected.add(index + 1)

            for i in affected:
                if is_peak_arr[i]:
                    is_peak_arr[i] = False
                    bit_update(i + 1, -1)

            nums[index] = val

            for i in affected:
                if is_peak(i):
                    is_peak_arr[i] = True
                    bit_update(i + 1, 1)

    return answer
